  title     String
  status    String   @default("open")
  createdAt DateTime @default(now())
}

import { prisma } from '../src/db.js';

// Sample data. Runs on every Run, so it only adds rows to an empty database.
// The count goes in a variable first: in this workspace, code like
// if ((await prisma.ticket.count()) === 0) at the top level of a file is skipped.
const ticketCount = await prisma.ticket.count();
if (ticketCount === 0) {
  await prisma.ticket.createMany({
    data: [
      { title: 'Printer is offline' },
      { title: 'Cannot log in to the VPN', status: 'in_progress' },
      { title: 'Laptop battery drains fast', status: 'closed' },
    ],
  });
  console.log('[seed] Added 3 tickets.');
}

await prisma.$disconnect();
process.exit(0); // the in-browser database would otherwise keep the script running

